#include <WiFi.h>

const char* ssid = "DIR-615T-0DBC";
const char* password = "23233010";

void WiFiGotIP(WiFiEvent_t event, WiFiEventInfo_t info) {
  Serial.println("\nWi-Fi подключен!");
  Serial.print("IP-адрес: ");
  Serial.println(WiFi.localIP());
}

void WiFiStationDisconnected(WiFiEvent_t event, WiFiEventInfo_t info) {
  Serial.println("\nСоединение потеряно. Переподключение...");
  WiFi.begin(ssid, password);
}

void setup() {
  Serial.begin(115200);
  delay(1000);

  // Регистрируем обработчики событий
  WiFi.onEvent(WiFiGotIP, WiFiEvent_t::ARDUINO_EVENT_WIFI_STA_GOT_IP);
  WiFi.onEvent(WiFiStationDisconnected, WiFiEvent_t::ARDUINO_EVENT_WIFI_STA_DISCONNECTED);

  WiFi.begin(ssid, password);
  Serial.println("Запуск подключения к Wi-Fi...");
}

void loop() {
  // Здесь может выполняться любой другой код, Wi-Fi работает в фоне
  delay(1000); 
}
